import os
import stat
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def _read_bytes(name: str) -> bytes | None:
    """Return the raw bytes of the regular file `name` inside `notes`,
    or None if it is missing, unreadable, not a regular file, or would
    resolve outside `notes`. Never raises for bad input."""
    try:
        base = Path(NOTES_DIR).resolve()
        target = (base / name).resolve()
        if target == base or not target.is_relative_to(base):
            return None
        flags = os.O_RDONLY | getattr(os, "O_NONBLOCK", 0) | getattr(os, "O_NOFOLLOW", 0)
        fd = os.open(target, flags)
        try:
            if not stat.S_ISREG(os.fstat(fd).st_mode):
                return None
            with os.fdopen(fd, "rb") as fh:
                fd = -1
                return fh.read()
        finally:
            if fd != -1:
                os.close(fd)
    except (OSError, ValueError, RuntimeError):
        return None


def read_note(name: str) -> str:
    """Return the text of the file `name` inside the directory `notes`
    (relative to the working directory).

    `name` is untrusted. It is resolved against `notes`, and anything that
    would end up outside `notes` (via "..", an absolute path, a symlink,
    a NUL byte, etc.) yields "". A missing, unreadable, non-regular or
    undecodable file also yields "". Never raises for bad input.
    """
    data = _read_bytes(name)
    if data is None:
        return ""
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        return ""


def count_readable(names: list[str]) -> int:
    """Count the entries of `names` that are regular files inside the
    directory `notes` and can be read.

    Each entry is counted separately, so duplicates count twice. An empty
    file that can be read counts. Names that are missing, are directories,
    are unreadable, or resolve (by "..", absolute path, symlink, NUL byte,
    or any other spelling) to a location outside `notes` do not count and
    never cause an exception.
    """
    return sum(1 for name in names if _read_bytes(name) is not None)


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    notes.mkdir()
    (notes / "a.txt").write_text("alpha")
    (notes / "b.txt").write_text("beta")
    (notes / "empty.txt").write_text("")
    (notes / "sub").mkdir()
    (notes / "sub" / "c.txt").write_text("gamma")
    (tmp_path / "secret.txt").write_text("top secret")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_count_basic(sandbox: Path) -> None:
    assert count_readable(["a.txt", "b.txt"]) == 2


def test_count_empty_list(sandbox: Path) -> None:
    assert count_readable([]) == 0


def test_count_missing_not_counted(sandbox: Path) -> None:
    assert count_readable(["a.txt", "nope.txt"]) == 1


def test_count_empty_file_counts(sandbox: Path) -> None:
    assert count_readable(["empty.txt"]) == 1


def test_count_duplicates_counted_each(sandbox: Path) -> None:
    assert count_readable(["a.txt", "a.txt", "b.txt"]) == 3


def test_count_nested_file(sandbox: Path) -> None:
    assert count_readable(["sub/c.txt"]) == 1


def test_count_directory_not_counted(sandbox: Path) -> None:
    assert count_readable(["sub", ""]) == 0


def test_count_dotdot_escape(sandbox: Path) -> None:
    assert count_readable(["../secret.txt", "sub/../../secret.txt"]) == 0


def test_count_absolute_path_escape(sandbox: Path) -> None:
    secret = str(sandbox / "secret.txt")
    assert count_readable([secret]) == 0


def test_count_nul_byte(sandbox: Path) -> None:
    assert count_readable(["a.txt\x00", "a\x00.txt"]) == 0


def test_count_symlink_escape(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert count_readable(["link.txt"]) == 0


def test_count_symlinked_dir_escape(sandbox: Path) -> None:
    outside = sandbox / "outside"
    outside.mkdir()
    (outside / "x.txt").write_text("x")
    try:
        (sandbox / NOTES_DIR / "d").symlink_to(outside, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks not supported")
    assert count_readable(["d/x.txt"]) == 0


def test_count_unreadable_file(sandbox: Path) -> None:
    path = sandbox / NOTES_DIR / "locked.txt"
    path.write_text("hidden")
    path.chmod(0)
    try:
        try:
            path.read_text()
        except OSError:
            pass
        else:
            pytest.skip("permissions not enforced (running as root?)")
        assert count_readable(["locked.txt", "a.txt"]) == 1
    finally:
        path.chmod(0o600)


def test_count_mixed(sandbox: Path) -> None:
    names = ["a.txt", "../secret.txt", "missing", "sub/c.txt", "sub", "b.txt"]
    assert count_readable(names) == 3


def test_read_note_contents(sandbox: Path) -> None:
    assert read_note("a.txt") == "alpha"
    assert read_note("sub/c.txt") == "gamma"
    assert read_note("empty.txt") == ""


def test_read_note_missing_is_empty(sandbox: Path) -> None:
    assert read_note("nope.txt") == ""
    assert read_note("sub") == ""
    assert read_note("") == ""


def test_read_note_never_escapes(sandbox: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note(str(sandbox / "secret.txt")) == ""
    assert read_note("sub/../../secret.txt") == ""
    assert read_note("a.txt\x00../secret.txt") == ""


def test_read_note_symlink_escape(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert read_note("link.txt") == ""


def test_read_note_unreadable_is_empty(sandbox: Path) -> None:
    path = sandbox / NOTES_DIR / "locked.txt"
    path.write_text("hidden")
    path.chmod(0)
    try:
        try:
            path.read_text()
        except OSError:
            pass
        else:
            pytest.skip("permissions not enforced (running as root?)")
        assert read_note("locked.txt") == ""
    finally:
        path.chmod(0o600)


def test_missing_notes_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    assert count_readable(["a.txt"]) == 0
    assert read_note("a.txt") == ""
    assert os.path.exists(tmp_path)
